WITH flattened AS (SELECT id, plan, effective_from, element FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS element), cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), effective_from) AS days_since_effective_from, LAST_DAY(effective_from) AS effective_from_month_end FROM flattened WHERE effective_from >= DATE '2024-03-15' AND effective_from <= '2025-05-01'), with_windows AS (SELECT *, SUM(element) OVER (PARTITION BY plan) AS plan_sum_element, RANK() OVER (ORDER BY days_since_effective_from DESC NULLS LAST) AS days_since_effective_from_rank, MIN(element) OVER (PARTITION BY plan) AS plan_min_element, MIN(days_since_effective_from) OVER (PARTITION BY plan) AS plan_min_days_since_effective_from FROM cleaned WHERE element < 52), cleaned_price_tiers AS (SELECT id, plan, effective_from, element, effective_from_month_end, plan_sum_element, plan_min_element, plan_min_days_since_effective_from, GREATEST(element, plan_min_element) AS greatest_element_plan_min_element FROM with_windows WHERE element <= 69) SELECT DATE_TRUNC('WEEK', effective_from_month_end) AS week_start, SIZE(COLLECT_SET(plan)) AS num_plans, SUM(CASE WHEN plan = 'enterprise' THEN plan_sum_element ELSE 0 END) AS enterprise_plan_sum_element, ROUND(AVG(greatest_element_plan_min_element), 2) AS avg_greatest_element_plan_min_element, APPROX_PERCENTILE(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, AVG(greatest_element_plan_min_element) FILTER (WHERE plan = 'basic') AS basic_avg_greatest_element_plan_min_element FROM cleaned_price_tiers GROUP BY DATE_TRUNC('WEEK', effective_from_month_end) HAVING AVG(greatest_element_plan_min_element) FILTER (WHERE plan = 'basic') > 0;
